import React, { useState } from 'react';
import { ChevronDown, X } from 'lucide-react';

const FAQ_DATA = [
  {
    id: 1,
    question: "Do you provide legal services for startups?",
    answer:
      "Absolutely! Our legal team specializes in startup formation, fundraising, and compliance. Whether you're a tech unicorn or a retail e-commerce, we tailor our advice to accelerate your growth.",
  },
  {
    id: 2,
    question: "What’s the turnaround time for document reviews?",
    answer:
      "We pride ourselves on quick turnaround times. For routine agreements, we aim to provide feedback within 24-48 hours. Complex matters may take up to a week, but we'll keep you updated every step of the way.",
  },
  {
    id: 3,
    question: "How do I schedule a consultation?",
    answer:
      "Simply fill out our quick form on the header or reach out directly to our intake team. We'll arrange a convenient time with one of our senior partners to discuss your case.",
  },
  {
    id: 4,
    question: "What’s the cost for a free initial consultation?",
    answer:
      "Our consultations are absolutely complimentary. There's no obligation to retain our services after the initial meeting. We want to ensure our expertise aligns with your legal needs.",
  },
  {
    id: 5,
    question: "Are your attorneys licensed in multiple jurisdictions?",
    answer:
      "Yes, our firm is licensed to practice in all major U.S. states and key international jurisdictions. We also collaborate with local counsel to ensure seamless representation across borders.",
  },
];

export default function Faq() {
  const [isClosedAll, setIsClosedAll] = useState(true);
  const [activeId, setActiveId] = useState(null);

  const toggleAccordion = (id) => {
    if (activeId === id) {
      setIsClosedAll(true);
      setActiveId(null);
    } else {
      setIsClosedAll(false);
      setActiveId(id);
    }
  };

  return (
    <div className="w-full max-w-5xl mx-auto p-6 sm:p-8 bg-slate-900 text-slate-100 rounded-2xl shadow-2xl backdrop-blur-xl border border-white/10">
      <div className="mb-8">
        <h2 className="text-2xl sm:text-3xl font-bold tracking-tight text-transparent bg-clip-text from-indigo-400 to-cyan-400 mb-4">
          Frequently Asked Questions
        </h2>
        <p className="text-slate-400 text-sm sm:text-base mb-6">
          Get the answers you need to move forward with confidence.
        </p>
      </div>

      {FAQ_DATA.map((faq) => {
        const isActive = activeId === faq.id;
        const isAllClosed = isClosedAll && activeId === null;

        return (
          <div
            key={faq.id}
            className="group relative mb-8 last:mb-0"
            onMouseEnter={() => setIsClosedAll(false)}
            onMouseLeave={() => setIsClosedAll(true)}
          >
            <div className="flex items-center justify-between gap-2 p-4 bg-white/5 border border-white/10 rounded-xl transition-all duration-300 hover:shadow-lg hover:scale-[1.02]">
              <div className="flex-1 space-y-1 text-left">
                <h3 className="text-base font-semibold text-slate-200 hover:text-white">
                  {faq.question}
                </h3>
                {!isActive && !isAllClosed && (
                  <p className="text-slate-400 text-sm">{faq.answer}</p>
                )}
              </div>
              {!isActive && (
                <button
                  className="hidden group-hover:block p-2 rounded-xl bg-white/5 text-slate-400 transition-colors hover:text-indigo-400"
                  onClick={() => toggleAccordion(faq.id)}
                >
                  <ChevronDown className="w-5 h-5" />
                </button>
              )}
              {isActive && (
                <button
                  className="p-2 rounded-xl bg-white/5 text-slate-400 hover:text-white transition-colors"
                  onClick={() => toggleAccordion(faq.id)}
                >
                  <X className="w-5 h-5" />
                </button>
              )}
            </div>

            {!isActive && !isAllClosed && (
              <div className="p-6 bg-white/5 rounded-xl border border-white/10">
                <p className="text-slate-400 text-sm sm:text-base">{faq.answer}</p>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

import React, { useState } from 'react';
import { Sparkles, Shield, ArrowRight, ChevronRight, DollarSign, Check, X, Zap, Globe, Mail, Calendar, CheckCircle2 } from 'lucide-react';

const PLANS = [
  {
    name: 'Basic',
    price: '149/mo',
    features: [
      { name: 'Single Attorney Access', icon: Globe, active: true },
      { name: 'Unlimited Case Tracking', icon: Check, active: true },
      { name: 'Basic E-Discovery Tools', icon: Zap, active: true },
      { name: '10 GB Storage Included', icon: Calendar, active: true },
      { name: 'Priority Email Support', icon: Mail, active: true },
    ],
    id: 'basic',
  },
  {
    name: 'Pro',
    price: '299/mo',
    features: [
      { name: 'Multi-Attorney Access', icon: Globe, active: true },
      { name: 'Advanced E-Discovery Suite', icon: Zap, active: true },
      { name: '50 GB Storage Included', icon: Calendar, active: true },
      { name: '24/7 Live Chat Support', icon: Mail, active: true },
      { name: 'Priority Phone Support', icon: Phone, active: true },
    ],
    id: 'pro',
  },
  {
    name: 'Enterprise',
    price: '599/mo',
    features: [
      { name: 'Custom Workflow Rules', icon: Zap, active: true },
      { name: 'Unlimited Storage & Performance', icon: Calendar, active: true },
      { name: 'Dedicated Account Manager', icon: Mail, active: true },
      { name: 'Advanced Security Compliance', icon: Shield, active: true },
      { name: 'Priority Onboarding & Training', icon: CheckCircle2, active: true },
    ],
    id: 'enterprise',
  },
];

export default function Pricing() {
  const [activePlan, setActivePlan] = useState('pro');

  return (
    <div className="w-full bg-slate-950 text-slate-100 font-sans antialiased min-h-screen flex items-center justify-center p-6 sm:p-12">
      {/* Decorative Background Gradient */}
      <div className="fixed -top-40 -right-40 w-96 h-96 bg-indigo-600/20 rounded-full blur-3xl pointer-events-none" />
      <div className="fixed -bottom-40 -left-40 w-96 h-96 bg-purple-600/20 rounded-full blur-3xl pointer-events-none" />

      <div className="w-full max-w-7xl mx-auto text-center sm:py-24">
        <div className="relative z-10 mb-12">
          <div className="absolute inset-x-0 top-[-6rem] -skew-y-12 transform backdrop-blur-xl bg-indigo-600/20/10 p-12" />
          <h2 className="text-3xl font-extrabold tracking-tight text-slate-100 sm:text-4xl">Pricing for Legal Excellence</h2>
          <p className="mt-3 text-slate-400 max-w-md mx-auto">Unlock unparalleled legal support tailored for your unique practice needs.</p>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {PLANS.map((plan) => (
            <div
              key={plan.id}
              className="relative overflow-hidden rounded-2xl bg-white/5 border border-white/10/10 p-6 transition-all duration-300 hover:shadow-2xl hover:scale-[1.02]"
            >
              <div className="absolute -top-12 -right-12 w-24 h-24 bg-gradient-to-br from-indigo-500/20 via-purple-500/20 to-pink-500/20 rounded-full shadow-lg shadow-indigo-500/30 opacity-75 pointer-events-none" />
              <div className="relative z-10 flex flex-col items-center gap-4">
                <div className="w-16 h-16 rounded-2xl bg-white/5 p-4 shadow-lg shadow-indigo-500/30 border border-white/20 flex items-center justify-center">
                  {plan.id === 'basic' ? <Sparkles className="w-6 h-6 text-indigo-400" /> : plan.id === 'pro' ? <Zap className="w-6 h-6 text-cyan-400" /> : <Shield className="w-6 h-6 text-purple-400" />}
                </div>
                <div className="text-center">
                  <h3 className="text-xl font-bold text-slate-100">{plan.name}</h3>
                  <p className="text-2xl font-bold tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-white to-transparent mt-1">
                    {plan.price}
                  </p>
                </div>
              </div>
              <div className="relative z-10 mt-6">
                {plan.features.map((feature, idx) => (
                  <div
                    key={feature.name}
                    className={`relative flex items-center justify-between gap-3 py-3 border-t border-white/10 mt-4 text-slate-400 transition-all duration-300 hover:scale-[1.02] ${
                      idx === 0 ? 'animate-in slide-in-from-top duration-500' : 'animate-in slide-in-from-bottom duration-500'
                    }`}
                  >
                    <div className="flex items-center gap-2">
                      {feature.active ? (
                        <div className="w-3 h-3 rounded-full bg-emerald-500/20 text-emerald-400" />
                      ) : (
                        <div className="w-3 h-3 rounded-full bg-rose-500/20 text-rose-400" />
                      )}
                      <div className="flex flex-col">
                        <span className="text-slate-400">{feature.icon?.name}</span>
                        <span className="text-slate-500 text-xs">{feature.name}</span>
                      </div>
                    </div>
                    {feature.active ? (
                      <Check className="w-4 h-4 text-emerald-400" />
                    ) : (
                      <X className="w-4 h-4 text-rose-400" />
                    )}
                  </div>
                ))}
              </div>
              <button
                onClick={() => setActivePlan(plan.id)}
                disabled={activePlan === plan.id}
                className="relative z-10 mt-8 inline-flex items-center gap-2 self-start px-6 py-3 rounded-2xl bg-white/5 text-slate-100 font-semibold border border-white/10 hover:border-white/20 transition-all duration-300 active:scale-95 group hover:shadow-lg"
              >
                {activePlan === plan.id ? 'Active Plan' : 'Select Plan'}
                <ArrowRight className="w-5 h-5 text-slate-400 group-hover:text-slate-200 transition-colors" />
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

